<script setup lang="ts">
import {computed,reactive,ref,onMounted,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import {listModelImports,importLabels,importActive} from '../api/modelImports'
import type {ModelImport} from '../types'
import {Box} from '@lucide/vue'
import PageHeading from '../components/common/PageHeading.vue'
import DetailModal from '../components/common/DetailModal.vue'
import FormModal from '../components/common/FormModal.vue'
import {useDemoStore} from '../stores/demo'
import type {Model} from '../types'
const router=useRouter(),imports=ref<ModelImport[]>([]),importError=ref('')
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
async function loadImports(){try{const data=await store.syncImportedModels();imports.value=data.jobs;importError.value=''}catch(e){importError.value=e instanceof Error?e.message:'导入服务不可用'}finally{if(!disposed)timer=setTimeout(loadImports,3000)}}
onMounted(loadImports);onBeforeUnmount(()=>{disposed=true;clearTimeout(timer)})
const store=useDemoStore(),search=ref(''),detail=ref<Model|null>(null),editing=ref(false),error=ref('')
const form=reactive({id:'',repo:'',environment:'',python:'',entry:''})
const rows=computed(()=>store.models.filter(m=>m.source!=='import').filter(m=>`${m.name} ${m.framework}`.toLowerCase().includes(search.value.toLowerCase())))
function edit(m:Model){Object.assign(form,m);error.value='';editing.value=true}
function editImported(id:string){const m=store.models.find(m=>m.id===id);if(m)edit(m)}
function save(){if([form.repo,form.environment,form.python,form.entry].some(v=>!v.trim())){error.value='请填写全部环境路径与训练入口。';return}const m=store.models.find(m=>m.id===form.id);if(m)Object.assign(m,{repo:form.repo,environment:form.environment,python:form.python,entry:form.entry,checked:false});store.persist();editing.value=false;store.notify('训练路径配置已保存；未移动文件或修改实际环境。')}
function check(m:Model){m.checked=true;store.persist();store.notify(`${m.name} 模拟检查完成；未执行系统命令，真实环境仍未连接。`)}
</script>
<template><PageHeading title="模型与环境" badge="本地管理" notice="预置模型为 Mock；新建模型会真实下载代码、权重并配置 Python 环境。" description="集中维护模型配置、Python 环境与训练入口。"><button class="button primary" @click="router.push('/models/new')">新建模型</button></PageHeading><div class="page-toolbar"><input v-model="search" aria-label="搜索模型" placeholder="搜索模型名称或 Framework…"/></div><p v-if="importError" class="form-error">{{importError}}</p><section v-if="imports.length" class="panel page-table" style="margin-bottom:24px"><table><thead><tr><th>真实导入模型</th><th>来源</th><th>状态</th><th>管理目录</th><th>操作</th></tr></thead><tbody><tr v-for="item in imports.filter(j=>j.name.toLowerCase().includes(search.toLowerCase()))" :key="item.id"><td>{{item.name}}</td><td>{{item.mode==='transfer'?'云端转移':item.provider==='huggingface'?'Hugging Face':item.provider==='modelscope'?'ModelScope':'未知来源'}}</td><td>{{importLabels[item.status]}}</td><td class="path-text">{{item.paths.root}}</td><td><button class="text-link" @click="router.push({path:'/models/new',query:{import:item.id}})">查看导入 / 日志</button><button v-if="item.status==='ready'" class="text-link" style="margin-left:10px" @click="editImported(item.id)">训练配置</button></td></tr></tbody></table></section><div class="catalog-grid"><section v-for="m in rows" :key="m.id" class="panel catalog-card"><div class="section-intro"><div><Box :size="28" style="color:var(--blue)"/><span class="catalog-badge">{{m.framework}}</span></div></div><h2>{{m.name}}</h2><p>{{m.description}}</p><dl class="summary-list"><div><dt>模型 ID</dt><dd>{{m.id}}</dd></div><div><dt>Python 环境</dt><dd class="path-text">{{m.environment}}</dd></div><div><dt>运行时 · Mock</dt><dd>Python {{m.version}} · PyTorch {{m.torch}}</dd></div><div><dt>环境状态</dt><dd>{{m.checked?'模拟检查通过 · 真实环境未连接':'Not Connected · 尚未模拟检查'}}</dd></div></dl><div class="row-actions"><button class="text-link" @click="detail=m">查看详情</button><button class="text-link" @click="check(m)">模拟检测</button><button class="text-link" @click="edit(m)">编辑配置</button></div></section></div><div v-if="!rows.length" class="panel empty-state">没有匹配的模型。</div><div class="info-note">下方预置模型为 Mock 配置；新建模型会真实下载代码与权重。真实导入结果在上方列表展示，训练仍为模拟。</div><DetailModal v-if="detail" :title="detail.name" :details="{'模型 ID':detail.id,'Framework':detail.framework,'Repository Path':detail.repo,'Python Environment':detail.environment,'Python Executable':detail.python,'Training Entry':detail.entry,'Python Version':detail.version,'PyTorch Version':detail.torch,'CUDA 状态':'未连接 · Mock','环境状态':detail.checked?'模拟检查通过':'未检查'}" @close="detail=null"/><FormModal v-if="editing" title="编辑训练路径配置" @close="editing=false"><form @submit.prevent="save"><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="form-grid"><label class="wide">Repository Path<input v-model="form.repo" required/></label><label class="wide">Python Environment<input v-model="form.environment" required/></label><label class="wide">Python Executable<input v-model="form.python" required/></label><label class="wide">Training Entry<input v-model="form.entry" required/></label></div><div class="form-actions"><button type="button" class="button" @click="editing=false">取消</button><button class="button primary">保存配置</button></div></form></FormModal></template>
